const headers = $json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const expected = 'Bearer ' + $env.PUBLISHING_N8N_AUTH_TOKEN;

if (authHeader !== expected) {
  return { json: { valid: false, statusCode: 401, error: 'PUBLISHING_WEBHOOK_UNAUTHORIZED: missing or invalid bearer token' } };
}

return { json: { valid: true, envelope: $json.body } };

const envelope = $json.envelope;
const errors = [];

if (!envelope || envelope.contract_version !== 'publishing-dispatch-envelope-v1') {
  errors.push('bad envelope contract_version');
}
if (!envelope || !envelope.body || envelope.body.contract_version !== 'publication-dispatch-v1') {
  errors.push('bad body contract_version');
}
if (!envelope || !envelope.body || !['real', 'manual_export', 'simulation'].includes(envelope.body.mode)) {
  errors.push('unknown or missing mode');
}
const requiredEnvelopeFields = ['message_id','sent_at','nonce','key_id','signature_algorithm','body_sha256','signature','body'];
for (const f of requiredEnvelopeFields) {
  if (envelope && envelope[f] === undefined) errors.push('missing envelope field: ' + f);
}

if (errors.length) {
  return { json: { valid: false, statusCode: 400, error: 'PUBLISHING_CONTRACT_UNSUPPORTED: ' + errors.join('; ') } };
}

return { json: { valid: true, envelope } };

function sortKeysDeep(value) {
  if (Array.isArray(value)) return value.map(sortKeysDeep);
  if (value !== null && typeof value === 'object') {
    const sorted = {};
    for (const key of Object.keys(value).sort()) {
      if (value[key] !== undefined) sorted[key] = sortKeysDeep(value[key]);
    }
    return sorted;
  }
  return value;
}
function canonicalJson(value) { return JSON.stringify(sortKeysDeep(value)); }
function sha256Hex(value) {
  return require('crypto').createHash('sha256').update(canonicalJson(value), 'utf8').digest('hex');
}
function sigInput({ contract_version, sent_at, nonce, body_sha256 }) {
  return ['hmac-sha256', contract_version, sent_at, nonce, body_sha256].join('\n');
}
function hmacHex(input, secret) {
  return require('crypto').createHmac('sha256', secret).update(sigInput(input), 'utf8').digest('hex');
}

const envelope = $json.envelope;
const secret = $env.PUBLISHING_N8N_SIGNING_SECRET;
const expectedKeyId = $env.PUBLISHING_N8N_SIGNING_KID;

const recomputedBodySha256 = sha256Hex(envelope.body);
if (recomputedBodySha256 !== envelope.body_sha256) {
  return { json: { valid: false, statusCode: 401, error: 'PUBLISHING_CANDIDATE_TAMPERED: body_sha256 mismatch' } };
}

const ageMs = Math.abs(Date.now() - Date.parse(envelope.sent_at));
if (ageMs > 300000) {
  return { json: { valid: false, statusCode: 401, error: 'PUBLISHING_WEBHOOK_TIMESTAMP_INVALID: outside 300s tolerance' } };
}

if (envelope.key_id !== expectedKeyId) {
  return { json: { valid: false, statusCode: 401, error: 'PUBLISHING_WEBHOOK_UNAUTHORIZED: unknown key_id' } };
}

const expectedSig = hmacHex({
  contract_version: envelope.contract_version,
  sent_at: envelope.sent_at,
  nonce: envelope.nonce,
  body_sha256: envelope.body_sha256,
}, secret);

const expectedBuf = Buffer.from(expectedSig, 'hex');
const receivedBuf = Buffer.from(envelope.signature || '', 'hex');
const sigValid = expectedBuf.length === receivedBuf.length && require('crypto').timingSafeEqual(expectedBuf, receivedBuf);

if (!sigValid) {
  return { json: { valid: false, statusCode: 401, error: 'PUBLISHING_WEBHOOK_UNAUTHORIZED: signature mismatch' } };
}

// Nonce-replay protection (issue #120). n8n staticData persists across
// executions on this instance; we record each dispatch nonce with a
// 10-minute TTL and reject an identical replay within that window as
// PUBLISHING_WEBHOOK_NONCE_REPLAYED. message_id is one-time-per-send.
const REPLAY_TTL_MS = 10 * 60 * 1000;
const store = $getWorkflowStaticData('global');
if (!store || typeof store !== 'object') {
  return { json: { valid: false, statusCode: 500, error: 'PUBLISHING_WEBHOOK_UNAUTHORIZED: nonce store unavailable' } };
}
const seen = store.__dispatch_nonces__ || {};
const now = Date.now();
for (const nk of Object.keys(seen)) {
  if (now - seen[nk] > REPLAY_TTL_MS) delete seen[nk];
}
if (Object.prototype.hasOwnProperty.call(seen, envelope.nonce)) {
  return { json: { valid: false, statusCode: 401, error: 'PUBLISHING_WEBHOOK_NONCE_REPLAYED: nonce seen within 10m' } };
}
seen[envelope.nonce] = now;
store.__dispatch_nonces__ = seen;

return { json: { valid: true, envelope } };

const https = require("https");
const crypto = require("crypto");

const env = $env || {};
const envelope = $json.envelope;
const body = envelope.body;
const candidate = body.candidate;
const target = body.target;
const assets = body.assets || [];
const asset = assets[0] || null;

function httpReq(method, urlStr, { headers, multipart, formData, binary, rawResponse } = {}) {
  return new Promise((resolve, reject) => {
    let u;
    try { u = new URL(urlStr); } catch (e) { return reject(new Error("bad url")); }
    const finalHeaders = { ...(headers || {}) };
    let payloadBuf = null;
    if (multipart) {
      const boundary = "----mmboundary" + crypto.randomBytes(16).toString("hex");
      finalHeaders["Content-Type"] = "multipart/form-data; boundary=" + boundary;
      const parts = [];
      for (const [k, v] of Object.entries(formData)) {
        parts.push("--" + boundary + "\r\nContent-Disposition: form-data; name=\"" + k + "\"\r\n\r\n" + v + "\r\n");
      }
      parts.push("--" + boundary + "\r\nContent-Disposition: form-data; name=\"source\"; filename=\"asset.png\"\r\nContent-Type: " + asset.mime_type + "\r\n\r\n");
      const head = Buffer.from(parts.join(""), "utf8");
      const tail = Buffer.from("\r\n--" + boundary + "--\r\n", "utf8");
      payloadBuf = Buffer.concat([head, binary, tail]);
      finalHeaders["Content-Length"] = payloadBuf.length;
    }
    const opts = { method, hostname: u.hostname, port: u.port || (u.protocol === "http:" ? 80 : 443), path: u.pathname + u.search, headers: finalHeaders };
    const req = https.request(opts, (res) => {
      const chunks = [];
      res.on("data", (c) => chunks.push(c));
      res.on("end", () => {
        const buf = Buffer.concat(chunks);
        resolve({ status: res.statusCode, headers: res.headers, body: buf.toString("utf8"), buf });
      });
    });
    req.on("error", reject);
    if (payloadBuf) req.end(payloadBuf); else req.end();
  });
}

function baseResult(outcome, extra) {
  return {
    contract_version: "publication-result-v1", result_id: crypto.randomUUID(),
    attempt_id: body.attempt_id, intent_id: body.intent_id, intent_version: body.intent_version,
    occurred_at: new Date().toISOString(), mode: "real", provider: "meta",
    remote_publication_id: null, remote_url: null, export_artifact_id: null,
    simulation_reference_id: null, simulation_label: null, error_code: null,
    retryable: false, reconciliation_required: false, ...outcome, ...extra,
  };
}

function mapGraphError(status, errObj) {
  const code = errObj && errObj.code;
  if (status === 401 || code === 190 || code === 102 || code === 463 || code === 467) return baseResult({ outcome: "failed" }, { error_code: "PUBLISHING_TARGET_UNAUTHORIZED", retryable: false });
  if (status === 429 || code === 4 || code === 17 || code === 32 || code === 613) return baseResult({ outcome: "failed" }, { error_code: "PUBLISHING_PROVIDER_RATE_LIMITED", retryable: true });
  if (status >= 400 && status < 500) return baseResult({ outcome: "failed" }, { error_code: "PUBLISHING_PROVIDER_FAILURE", retryable: false });
  return baseResult({ outcome: "failed" }, { error_code: "PUBLISHING_PROVIDER_FAILURE", retryable: true });
}

// AMBIGUOUS delivery classifier: a network error mid/after upload means Meta
// may already have published — never retry, surface unknown + reconciliation.
function isAmbiguousSendError(err) {
  const m = String(err && err.code || err && err.message || err);
  return /ETIMEDOUT|ESOCKETTIMEDOUT|ECONNRESET|EPIPE|ECONNABORTED/.test(m);
}

let assetBytes;
try {
  if (!asset) throw new Error("no asset");
  if (asset.retrieval_expires_at && Date.parse(asset.retrieval_expires_at) < Date.now()) {
    return { json: { envelope, result: baseResult({ outcome: "failed" }, { error_code: "PUBLISHING_ASSET_UNAVAILABLE", retryable: false }) } };
  }
  const r = await httpReq("GET", asset.retrieval_url, { headers: { "x-publishing-internal-token": env.PUBLISHING_INTERNAL_SERVICE_TOKEN || "" } });
  if (r.status !== 200 || !r.buf || r.buf.length === 0) {
    return { json: { envelope, result: baseResult({ outcome: "failed" }, { error_code: "PUBLISHING_ASSET_UNAVAILABLE", retryable: true }) } };
  }
  assetBytes = r.buf;
} catch (e) {
  return { json: { envelope, result: baseResult({ outcome: "failed" }, { error_code: "PUBLISHING_ASSET_UNAVAILABLE", retryable: true }) } };
}

const pageId = env.META_TEST_PAGE_ID || (target && target.external_account_id) || "";
const token = env.META_TEST_PAGE_ACCESS_TOKEN || "";
if (!pageId || !token) {
  return { json: { envelope, result: baseResult({ outcome: "failed" }, { error_code: "PUBLISHING_TARGET_UNAUTHORIZED", retryable: false }) } };
}

const hashtags = Array.isArray(candidate.hashtags) ? candidate.hashtags.join(" ") : "";
const caption = [candidate.caption, hashtags].filter(Boolean).join("\n");

let uploaded;
let graphError = null;
try {
  uploaded = await httpReq("POST", "https://graph.facebook.com/v19.0/" + pageId + "/photos?access_token=" + encodeURIComponent(token), {
    multipart: true, formData: { caption, published: "true" }, binary: assetBytes,
  });
} catch (e) {
  if (isAmbiguousSendError(e)) {
    return { json: { envelope, result: baseResult({ outcome: "unknown" }, { error_code: "PUBLISHING_PROVIDER_OUTCOME_UNKNOWN", reconciliation_required: true }) } };
  }
  return { json: { envelope, result: baseResult({ outcome: "failed" }, { error_code: "PUBLISHING_PROVIDER_FAILURE", retryable: true }) } };
}

let parsed;
try { parsed = JSON.parse(uploaded.body); } catch (e) { parsed = null; }

if (!parsed || parsed.error || uploaded.status >= 400) {
  const mapped = mapGraphError(uploaded.status, parsed && parsed.error);
  return { json: { envelope, result: mapped } };
}

const photoId = parsed.id;
const remotePublicationId = parsed.post_id || (pageId + "_" + photoId);

let remoteUrl = null;
try {
  const link = await httpReq("GET", "https://graph.facebook.com/v19.0/" + photoId + "?fields=link&access_token=" + encodeURIComponent(token));
  const lj = JSON.parse(link.body);
  if (lj && typeof lj.link === "string") remoteUrl = lj.link;
} catch (e) { /* permalink best-effort — still published */ }

return { json: { envelope, result: baseResult({ outcome: "published" }, {
  remote_publication_id: remotePublicationId, remote_url: remoteUrl,
}) } };

const crypto = require("crypto");
const envelope = $json.envelope;
const body = envelope.body;
const candidate = body.candidate;
const assets = body.assets || [];

// Assemble the export manifest: caption, hashtags, alt_text, and every asset
// with its signed checksum. n8n emits the archive as a binary item (JSON
// manifest) so the API records a real export_artifact_id for the owner.
const manifest = {
  contract_version: "publishing-export-manifest-v1",
  intent_id: body.intent_id,
  candidate_id: candidate.candidate_id,
  caption: candidate.caption,
  cta: candidate.cta,
  hashtags: candidate.hashtags,
  alt_text: candidate.alt_text,
  assets: assets.map((a) => ({ asset_id: a.asset_id, mime_type: a.mime_type, checksum: a.checksum })),
  manifest_checksum: "", // stamped below
  generated_at: new Date().toISOString(),
};
const manifestChecksum = crypto.createHash("sha256").update(JSON.stringify({ ...manifest, manifest_checksum: "" }), "utf8").digest("hex");
manifest.manifest_checksum = manifestChecksum;

const artifactId = crypto.randomUUID();
const result = {
  contract_version: "publication-result-v1",
  result_id: crypto.randomUUID(),
  attempt_id: body.attempt_id,
  intent_id: body.intent_id,
  intent_version: body.intent_version,
  occurred_at: new Date().toISOString(),
  mode: "manual_export",
  outcome: "exported",
  provider: null,
  remote_publication_id: null,
  remote_url: null,
  export_artifact_id: artifactId,
  simulation_reference_id: null,
  simulation_label: null,
  error_code: null,
  retryable: false,
  reconciliation_required: false,
};
// Emit the manifest as a binary item alongside the result so downstream nodes
// (or an archive sink) can persist it; the artifact_id binds the two.
const manifestJson = Buffer.from(JSON.stringify(manifest, null, 2), "utf8");
return [
  { json: { envelope, result, manifest, artifact_id: artifactId }, binary: { manifest: { data: manifestJson.toString("base64"), mimeType: "application/json", fileName: "manifest.json" } } },
];

const crypto = require("crypto");
const envelope = $json.envelope;
const body = envelope.body;
// SIMULATION performs NO external request and emits a deterministic fake
// remote identity scoped to the attempt. simulation_label is "SIMULATION"
// end-to-end so the stored result can never be mistaken for a real post.
const result = {
  contract_version: "publication-result-v1",
  result_id: crypto.randomUUID(),
  attempt_id: body.attempt_id,
  intent_id: body.intent_id,
  intent_version: body.intent_version,
  occurred_at: new Date().toISOString(),
  mode: "simulation",
  outcome: "simulated",
  provider: null,
  remote_publication_id: null,
  remote_url: null,
  export_artifact_id: null,
  simulation_reference_id: "sim-" + body.attempt_id,
  simulation_label: "SIMULATION",
  error_code: null,
  retryable: false,
  reconciliation_required: false,
};
return { json: { envelope, result } };

const envelope = $json.envelope;
const result = $json.result;

const callbackBody = {
  contract_version: 'publication-callback-v1',
  callback_id: require('crypto').randomUUID(),
  attempt_id: envelope.body.attempt_id,
  intent_id: envelope.body.intent_id,
  intent_version: envelope.body.intent_version,
  request_fingerprint: envelope.body_sha256,
  workflow_version: envelope.body.workflow_version,
  result,
};

return { json: { callbackBody, callback_url: envelope.body.callback_url } };

